import numpy as np, random, scipy.sparse as sp, scipy.sparse.linalg as spla
from reference import Task

def solve_custom(prob, ncv=30, tol=0):
    A=prob['matrix']; k=prob['k']; N=A.shape[0]; v0=np.ones(N, dtype=A.dtype)
    vals, vecs=spla.eigs(A, k=k, v0=v0, ncv=ncv, tol=tol, maxiter=N*200)
    pairs=list(zip(vals, vecs.T)); pairs.sort(key=lambda p:-abs(p[0]))
    return [p[1] for p in pairs]

def test(ncv,tol):
    for seed in range(15):
        prob=Task().generate_problem(300, random_seed=seed)
        ref=Task().solve(prob)
        cand=solve_custom(prob,ncv=ncv,tol=tol)
        for r,c in zip(ref,cand):
            sim=np.abs(np.dot(np.conj(r)/np.linalg.norm(r), c/np.linalg.norm(c)))
            if not np.isclose(sim,1.0, atol=1e-6):
                return False
    return True

for ncv in [25,30,35,40,50]:
    for tol in [0,1e-6,1e-7]:
        print('ncv',ncv,'tol',tol,'pass',test(ncv,tol))
